import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-6 p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
    >
      {children}
    </div>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";
import InterfaceExample from "./variants/interface";
const InterfaceSource = "import { Button } from "@/registry/erbium/ui/button";
import {
  Card,
  CardHeader,
  CardTitle,
  CardDescription,
  CardContent,
  CardFooter,
} from "@/registry/erbium/ui/card";
import { Input } from "@/registry/erbium/ui/input";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";

export default function InterfaceExample() {
  return (
    <div className="grid w-full gap-6 lg:grid-cols-2">
      <section className="grid content-start gap-4" aria-label="Typography roles">
        <h1 className="text-display">A place for your team</h1>
        <h2 className="text-title">Work together</h2>
        <h3 className="text-subtitle">Keep projects moving</h3>
        <p className="text-body max-w-[65ch]">
          Share progress, invite collaborators, and give every project a clear next step.
        </p>
        <p className="text-caption text-muted-foreground">
          Your preferences apply to this workspace.
        </p>
      </section>
      <Card className="w-full max-w-md">
        <CardHeader>
          <CardTitle>Workspace preferences</CardTitle>
          <CardDescription>Update the name shown to workspace members.</CardDescription>
        </CardHeader>
        <CardContent className="grid gap-2">
          <Field>
            <FieldLabel htmlFor="typography-workspace">Workspace name</FieldLabel>
            <Input id="typography-workspace" defaultValue="Erbium Studio" />
          </Field>
          <p className="text-caption text-muted-foreground">Use a name your team will recognize.</p>
        </CardContent>
        <CardFooter>
          <Button>Save preferences</Button>
        </CardFooter>
      </Card>
    </div>
  );
}
";
import CodeExample from "./variants/code";
const CodeSource = "import { CodeBlock } from "@/registry/erbium/blocks/code-block";

export default function CodeExample() {
  return (
    <div className="flex w-full max-w-lg flex-col gap-4">
      <CodeBlock surface="command" language="shell" code="bunx shadcn@latest add @erbium/button" />
      <CodeBlock title="button.tsx" language="tsx" code="<Button>Continue</Button>" />
    </div>
  );
}
";
import ReadingExample from "./variants/reading";
const ReadingSource = "import { Card, CardHeader, CardTitle, CardContent } from "@/registry/erbium/ui/card";

export default function ReadingExample() {
  return (
    <div className="grid w-full gap-4 lg:grid-cols-2">
      {(["docs", "compact"] as const).map((preset) => (
        <Card key={preset}>
          <CardHeader>
            <CardTitle>{preset === "docs" ? "Default reading" : "Compact reading"}</CardTitle>
          </CardHeader>
          <CardContent>
            <article className={`typeset typeset-${preset} max-w-[65ch]`}>
              <h2>Workspace access</h2>
              <p>
                Members can view shared projects. Administrators can also manage access and
                workspace settings.
              </p>
              <p>
                Changes apply to <strong>all workspace members</strong>. Invitations remain{" "}
                <em>pending</em> until accepted.
              </p>
              <ul>
                <li>Review member roles before granting access.</li>
                <li>Remove access when a member leaves the team.</li>
                <li>
                  Keep access deliberate.
                  <ul>
                    <li>Invite collaborators to the projects they need.</li>
                  </ul>
                </li>
              </ul>
              <blockquote>
                <p>A clear next step helps everyone keep work moving.</p>
              </blockquote>
              <p>
                Use <code>workspace.members</code> to inspect the current members.
              </p>
              <div
                className="typeset-scroll"
                tabIndex={0}
                role="region"
                aria-label="Workspace role comparison"
              >
                <table>
                  <caption>Access by workspace role</caption>
                  <thead>
                    <tr>
                      <th>Role</th>
                      <th>Projects</th>
                      <th>Members</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr>
                      <th>Member</th>
                      <td>View</td>
                      <td>24</td>
                    </tr>
                    <tr>
                      <th>Administrator</th>
                      <td>Manage</td>
                      <td>3</td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </article>
          </CardContent>
        </Card>
      ))}
    </div>
  );
}
";
import MultilingualExample from "./variants/multilingual";
const MultilingualSource = "import { Button } from "@/registry/erbium/ui/button";
import {
  Card,
  CardHeader,
  CardTitle,
  CardDescription,
  CardContent,
  CardFooter,
} from "@/registry/erbium/ui/card";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { Input } from "@/registry/erbium/ui/input";

export default function MultilingualExample() {
  return (
    <div className="grid w-full gap-4 lg:grid-cols-2">
      <Card dir="rtl" lang="fa">
        <CardHeader>
          <CardTitle>تنظیمات فضای کاری</CardTitle>
          <CardDescription>متن فارسی با فونت وزیرمتن نمایش داده می‌شود.</CardDescription>
        </CardHeader>
        <CardContent className="grid gap-2">
          <Field>
            <FieldLabel htmlFor="typography-persian">نام فضای کاری</FieldLabel>
            <Input id="typography-persian" defaultValue="استودیوی اربیوم" />
          </Field>
          <p className="text-body">فضای کاری Erbium برای همکاری تیم شما.</p>
        </CardContent>
        <CardFooter>
          <Button>ذخیره تنظیمات</Button>
        </CardFooter>
      </Card>
      <Card dir="rtl" lang="ar">
        <CardHeader>
          <CardTitle>إعدادات مساحة العمل</CardTitle>
          <CardDescription>النص العربي يستخدم نفس الأدوار الطباعية.</CardDescription>
        </CardHeader>
        <CardContent className="grid gap-2">
          <Field>
            <FieldLabel htmlFor="typography-arabic">اسم مساحة العمل</FieldLabel>
            <Input id="typography-arabic" defaultValue="استوديو إربيوم" />
          </Field>
          <p className="text-body">مساحة عمل Erbium لفريقك.</p>
        </CardContent>
        <CardFooter>
          <Button>حفظ الإعدادات</Button>
        </CardFooter>
      </Card>
    </div>
  );
}
";
const meta = {
  parameters: {
    docs: { description: { component: "Use Cal Sans for Latin interfaces, Vazirmatn for Arabic and Persian, and Paper Mono for code. See the [typography setup guide](/docs/typography) for installation, lazy font loading, and customization." } },
    layout: "fullscreen",
  },
} satisfies Meta;
export default { ...meta, title: "Foundations/Typography",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;
type Story = StoryObj;
export const Interface: Story = {
  parameters: {
    docs: {
      description: { story: "Five text roles in Cal Sans, with shared title and description defaults in real controls." },
      source: { code: InterfaceSource },
    },
  },
  render: InterfaceExample,
};
export const Code: Story = {
  parameters: {
    docs: {
      description: { story: "Paper Mono in command and source samples using the shared code block." },
      source: { code: CodeSource },
    },
  },
  render: CodeExample,
};
export const Reading: Story = {
  parameters: {
    docs: {
      description: { story: "Shared heading roles with explicit default and compact reading rhythms." },
      source: { code: ReadingSource },
    },
  },
  render: ReadingExample,
};
export const Multilingual: Story = {
  parameters: {
    docs: {
      description: { story: "Vazirmatn in Persian and Arabic interfaces, with mixed Latin text and RTL layout." },
      source: { code: MultilingualSource },
    },
  },
  render: MultilingualExample,
};

import { CodeBlock } from "@/registry/erbium/blocks/code-block";

export default function CodeExample() {
  return (
    <div className="flex w-full max-w-lg flex-col gap-4">
      <CodeBlock surface="command" language="shell" code="bunx shadcn@latest add @erbium/button" />
      <CodeBlock title="button.tsx" language="tsx" code="<Button>Continue</Button>" />
    </div>
  );
}
